#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 20, 4); // Адрес I2C дисплея (подставьте свой при необходимости)

// ---------- Пины ----------
const int button1Pin = 3; // Кнопка 1 (короткое: изменение цифры, длинное: переход на следующую цифру)
const int button2Pin = 4; // Кнопка 2 (короткое: выбор раздела, длинное: запуск Burst)
const int outputPin = 9; // Выход на оптопару (ШИМ/импульсы)

// ---------- Параметры генерации ----------
unsigned long pulseWidth = 100; // Длительность импульса (мкс)
unsigned long pauseWidth = 100; // Длительность паузы (мкс)
unsigned long burstCount = 1; // Число импульсов в пачке (Burst)

// Символьные представления для ввода (6 цифр)
char pulseDigits[6] = {'0', '0', '0', '1', '0', '0'}; // "000100" -> 100 мкс
char pauseDigits[6] = {'0', '0', '0', '1', '0', '0'};
char burstDigits[6] = {'0', '0', '0', '0', '0', '1'}; // "000001" -> 1 импульс

// ---------- Интерфейс ----------
int currentSection = 0; // 0 = pulse, 1 = pause, 2 = mode, 3 = burst count (только в Burst-режиме)
int currentDigit = 0; // Индекс редактируемой цифры (0-5)
int mode = 1; // 0 = Continuous, 1 = Burst

volatile bool generating = false; // Флаг активной генерации пачки

// ---------- Дребезг кнопок ----------
int button1State = HIGH, lastButton1Reading = HIGH;
unsigned long lastDebounceTime1 = 0, button1PressTime = 0;
int button2State = HIGH, lastButton2Reading = HIGH;
unsigned long lastDebounceTime2 = 0, button2PressTime = 0;
const unsigned long debounceDelay = 50; // мс
const unsigned long longPressThreshold = 400; // мс (удержание кнопки)

// ---------- Вспомогательные функции ----------
unsigned long getValue(char* digits) {
 unsigned long val = 0;
 for (int i = 0; i < 6; i++) {
 val = val * 10 + (digits[i] - '0');
 }
 return (val == 0) ? 1 : val; // 000000 интерпретируется как 1 мкс
}

// Настройка аппаратного ШИМ (режим Continuous)
void configureTimer() {
 unsigned long period_us = pulseWidth + pauseWidth;
 if (period_us > 1000000) period_us = 1000000; // ограничение 1 сек

 uint16_t prescaler;
 uint8_t cs_bits;
 double tick_us;

 if (period_us <= 4096) {
 prescaler = 1; cs_bits = 0b001; tick_us = 0.0625;
 } else if (period_us <= 32768) {
 prescaler = 8; cs_bits = 0b010; tick_us = 0.5;
 } else if (period_us <= 262144) {
 prescaler = 64; cs_bits = 0b011; tick_us = 4.0;
 } else if (period_us <= 1048576) {
 prescaler = 256; cs_bits = 0b100; tick_us = 16.0;
 } else {
 prescaler = 1024; cs_bits = 0b101; tick_us = 64.0;
 }

 double clock_mhz = 16.0;
 double ticks_period = (period_us * clock_mhz) / prescaler;
 uint16_t icr = round(ticks_period) - 1;
 if (icr < 1) icr = 1;

 double ticks_high = (pulseWidth * clock_mhz) / prescaler;
 uint16_t ocr = round(ticks_high) - 1;
 if (ocr > icr) ocr = icr;
 if (ocr < 0) ocr = 0;

 noInterrupts();
 TCCR1A = 0;
 TCCR1B = 0;
 TCNT1 = 0;
 ICR1 = icr;
 OCR1A = ocr;
 // Инвертированный fast PWM (чтобы HIGH на выходе оптопары соответствовал открытому MOSFET)
 TCCR1A = (1 << COM1A1) | (1 << COM1A0) | (1 << WGM11);
 TCCR1B = (1 << WGM13) | (1 << WGM12) | cs_bits;
 interrupts();
}

// Обновление дисплея с мигающим курсором
void updateDisplay() {
 lcd.clear();
 lcd.setCursor(0, 0);
 lcd.print("Pulse: ");
 for (int i = 0; i < 6; i++) lcd.print(pulseDigits[i]);
 lcd.print(" us");

 lcd.setCursor(0, 1);
 lcd.print("Pause: ");
 for (int i = 0; i < 6; i++) lcd.print(pauseDigits[i]);
 lcd.print(" us");

 lcd.setCursor(0, 2);
 lcd.print("Mode: ");
 if (mode == 0) lcd.print("Continuous");
 else lcd.print("Burst");

 if (mode == 1) {
 lcd.setCursor(0, 3);
 lcd.print("Burst: ");
 for (int i = 0; i < 6; i++) lcd.print(burstDigits[i]);
 }

 // Мигающий курсор
 int row, col;
 if (currentSection == 0) { row = 0; col = 7 + currentDigit; }
 else if (currentSection == 1) { row = 1; col = 7 + currentDigit; }
 else if (currentSection == 2) { row = 2; col = 6; }
 else { row = 3; col = 7 + currentDigit; }
 lcd.setCursor(col, row);
 lcd.blink();
}

// ---------- Инициализация ----------
void setup() {
 pinMode(button1Pin, INPUT_PULLUP);
 pinMode(button2Pin, INPUT_PULLUP);
 pinMode(outputPin, OUTPUT);

 // Начальное состояние: светодиод оптопары горит -> выход LOW -> MOSFET закрыт
 digitalWrite(outputPin, HIGH);

 lcd.init();
 lcd.backlight();

 pulseWidth = getValue(pulseDigits);
 pauseWidth = getValue(pauseDigits);
 burstCount = getValue(burstDigits);

 if (mode == 0) configureTimer(); // Если Continuous, запускаем таймер
 updateDisplay();
}

// ---------- Основной цикл ----------
void loop() {
 // 🔘 Кнопка 1 (изменение значений)
 int reading1 = digitalRead(button1Pin);
 if (reading1 != lastButton1Reading) {
 lastDebounceTime1 = millis();
 }
 if ((millis() - lastDebounceTime1) > debounceDelay) {
 if (reading1 != button1State) {
 button1State = reading1;
 if (button1State == LOW) {
 button1PressTime = millis(); // нажали
 } else {
 // Отпустили кнопку
 unsigned long duration = millis() - button1PressTime;
 bool paramsChanged = false;

 if (currentSection == 0 || currentSection == 1 || (currentSection == 3 && mode == 1)) {
 char* digits = (currentSection == 0) ? pulseDigits :
 (currentSection == 1) ? pauseDigits : burstDigits;
 if (duration < longPressThreshold) {
 // Короткое нажатие: увеличить цифру
 digits[currentDigit]++;
 if (digits[currentDigit] > '9') digits[currentDigit] = '0';
 paramsChanged = true;
 } else {
 // Длинное нажатие: переход к следующей цифре
 currentDigit = (currentDigit + 1) % 6;
 }
 } else if (currentSection == 2) {
 // Раздел Mode: короткое нажатие переключает Continuous/Burst
 if (duration < longPressThreshold) {
 mode = (mode + 1) % 2;
 paramsChanged = true;
 }
 }

 // Если параметры изменились, пересчитываем и сбрасываем генератор
 if (paramsChanged) {
 // Принудительно закрываем MOSFET
 digitalWrite(outputPin, HIGH);
 noInterrupts();
 TCCR1A = 0; // остановка таймера
 TCCR1B = 0;
 interrupts();
 generating = false;

 pulseWidth = getValue(pulseDigits);
 pauseWidth = getValue(pauseDigits);
 burstCount = getValue(burstDigits);

 if (mode == 0) configureTimer(); // перезапустить Continuous, если нужно
 }
 updateDisplay();
 }
 }
 }
 lastButton1Reading = reading1;

 // 🔘 Кнопка 2 (переключение разделов и запуск Burst)
 int reading2 = digitalRead(button2Pin);
 if (reading2 != lastButton2Reading) {
 lastDebounceTime2 = millis();
 }
 if ((millis() - lastDebounceTime2) > debounceDelay) {
 if (reading2 != button2State) {
 button2State = reading2;
 if (button2State == LOW) {
 button2PressTime = millis();
 } else {
 unsigned long duration = millis() - button2PressTime;

 if (duration < longPressThreshold) {
 // Короткое нажатие: выбор следующего раздела меню
 currentSection = (currentSection + 1) % (mode == 0 ? 3 : 4);
 currentDigit = 0;
 } else {
 // Длинное нажатие: запустить пачку (только в режиме Burst)
 if (mode == 1 && !generating && burstCount > 0) {
 generating = true;

 // Задаём длительности без коррекции (6N137 быстрая)
 unsigned long pulseEffective = pulseWidth;
 unsigned long pauseEffective = pauseWidth;

 for (unsigned long i = 0; i < burstCount; i++) {
 // Быстрый LOW: сбрасываем бит 1 порта B
 PORTB &= ~(1 << PB1);
 delayMicroseconds(pulseEffective);

 // Быстрый HIGH: устанавливаем бит 1 порта B
 PORTB |= (1 << PB1);

 if (i < burstCount - 1) {
 delayMicroseconds(pauseEffective);
 }
 }
 generating = false;
 }
 }
 updateDisplay();
 }
 }
 }
 lastButton2Reading = reading2;

 // Если режим Continuous и таймер остановлен (например, был сброс параметров),
 // он автоматически не перезапустится, но в setup() и при изменении настроек мы его запускаем.
}
